python3 << 'EOF'
import re

txt = open('eprint/bothd.eps').read()
# extract page content after EndPageSetup
body = txt.split('%%EndPageSetup')[1]

# tokenize: join continuation lines; paths end with P, S, f, etc.
tokens = body.split()
paths = []
cur = []
i = 0
while i < len(tokens):
    t = tokens[i]
    try:
        cur.append(float(t))
    except ValueError:
        if t in ('P','S','H','h','f','f*','s'):
            if cur:
                paths.append((t, cur[:]))
            cur = []
        else:
            cur = []  # other operator, reset numeric buffer
    i += 1

# reconstruct polylines for P/S paths: first pair absolute moveto, rest relative
polys = []
for op, nums in paths:
    if len(nums) >= 4 and len(nums) % 2 == 0:
        x, y = nums[0], nums[1]
        pts = [(x, y)]
        for k in range(2, len(nums), 2):
            x += nums[k]; y += nums[k+1]
            pts.append((x, y))
        polys.append((op, pts))

# left-axis ticks: lines starting at x=5392 going right (74.4 or 148.8)
for op, pts in polys:
    if len(pts) == 2 and abs(pts[0][0]-5392) < 1 and abs(pts[1][1]-pts[0][1]) < 0.01:
        length = pts[1][0]-pts[0][0]
        if length > 100:
            print('MAJOR y-tick at', pts[0][1])
