    except ValueError:
        if t in ('P','S','H','h','f','f*','s') and cur: paths.append((t,cur[:]))
        cur = []
polys = []
for op, nums in paths:
    if len(nums)>=4 and len(nums)%2==0:
        x,y = nums[0],nums[1]; pts=[(x,y)]
        for k in range(2,len(nums),2):
            x+=nums[k]; y+=nums[k+1]; pts.append((x,y))
        polys.append((op,pts))

polys.sort(key=lambda p: -len(p[1]))
for op,pts in polys[:8]:
    xs=[p[0] for p in pts]; ys=[p[1] for p in pts]
    print(op, len(pts), 'x:', round(min(xs)),round(max(xs)), 'y:', round(min(ys)),round(max(ys)), 'start',pts[0],'end',pts[-1])
